#[repr(u8)]
#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
pub enum BlockId {
    Air = 0,
    Grass = 1,
    Dirt = 2,
    Stone = 3,
    Cobblestone = 4,
    Sand = 5,
    OakLog = 6,
    OakLeaves = 7,
    OakPlanks = 8,
    Brick = 9,
    Snow = 10,
    Bedrock = 11,
    CoalOre = 12,
    IronOre = 13,
    /// Durable, placeable crafting station produced by the 2x2 plank recipe.
    CraftingTable = 14,
    /// Worldgen-only sea liquid. Generated by the terrain pass in ocean basins
    /// below the named sea level, never placed by the player, never persisted
    /// into a chunk edit, and never carried as an item.
    Water = 15,
}

impl BlockId {
    /// Whether this block blocks movement, sight lines, and light.
    ///
    /// Air and water are the passable, transparent ids: both are skipped by
    /// collision, raycast hits, opaque meshing, and sky-light occlusion.
    #[inline]
    pub const fn is_solid(self) -> bool {
        !matches!(self, BlockId::Air | BlockId::Water)
    }

    /// Whether this block is a liquid volume rather than a solid block.
    ///
    /// Deliberately narrow (only water today): the mobility/placement rules
    /// added with the ocean basins consume this predicate instead of
    /// enumerating ids at each call site.
    #[inline]
    pub const fn is_liquid(self) -> bool {
        matches!(self, BlockId::Water)
    }

    /// Whether right-clicking this block opens a crafting station interface.
    ///
    /// Deliberately narrow: the crafting table is the only interactive
    /// station today, so every other block (including Air and unbreakable
    /// terrain) falls through to the placement/interaction-free path. Solid,
    /// breakable, and texture behavior are untouched by this classification.
    #[inline]
    pub const fn is_table_interactable(self) -> bool {
        matches!(self, BlockId::CraftingTable)
    }

    #[inline]
    pub const fn from_u8(v: u8) -> Option<Self> {
        match v {
            0 => Some(BlockId::Air),
            1 => Some(BlockId::Grass),
            2 => Some(BlockId::Dirt),
            3 => Some(BlockId::Stone),
            4 => Some(BlockId::Cobblestone),
            5 => Some(BlockId::Sand),
            6 => Some(BlockId::OakLog),
            7 => Some(BlockId::OakLeaves),
            8 => Some(BlockId::OakPlanks),
            9 => Some(BlockId::Brick),
            10 => Some(BlockId::Snow),
            11 => Some(BlockId::Bedrock),
            12 => Some(BlockId::CoalOre),
            13 => Some(BlockId::IronOre),
            14 => Some(BlockId::CraftingTable),
            15 => Some(BlockId::Water),
            _ => None,
        }
    }

    /// Returns texture array layer index (0..16) for a face direction:
    /// 0 = +X, 1 = -X, 2 = +Y (top), 3 = -Y (bottom), 4 = +Z, 5 = -Z
    #[inline]
    pub const fn face_tex_layer(self, face_dir: u8) -> u8 {
        match self {
            BlockId::Air => 0,
            BlockId::Grass => match face_dir {
                2 => 0, // grass top
                3 => 2, // dirt bottom
                _ => 1, // grass side
            },
            BlockId::Dirt => 2,
            BlockId::Stone => 3,
            BlockId::Cobblestone => 4,
            BlockId::Sand => 5,
            BlockId::OakLog => match face_dir {
                2 | 3 => 6, // log top/bottom
                _ => 7,     // log bark side
            },
            BlockId::OakLeaves => 8,
            BlockId::OakPlanks => 9,
            BlockId::Brick => 10,
            BlockId::Snow => match face_dir {
                2 => 11, // snow top
                3 => 2,  // dirt bottom
                _ => 13, // snow grass side
            },
            BlockId::Bedrock => 12,
            BlockId::CoalOre => 14,
            BlockId::IronOre => 15,
            // No dedicated crafting-table texture exists yet; reuse the oak
            // plank layer so the block reads as wood until pack art arrives.
            BlockId::CraftingTable => 9,
            // Placeholder only: water surfaces are carried on a separate,
            // deliberately un-uploaded mesh field, so this layer is never
            // sampled by the opaque GPU path. Kept inside 0..=15 so the
            // texture-array index stays valid if that ever changes.
            BlockId::Water => 0,
        }
    }

    pub const fn name(self) -> &'static str {
        match self {
            BlockId::Air => "Air",
            BlockId::Grass => "Grass",
            BlockId::Dirt => "Dirt",
            BlockId::Stone => "Stone",
            BlockId::Cobblestone => "Cobblestone",
            BlockId::Sand => "Sand",
            BlockId::OakLog => "Oak Log",
            BlockId::OakLeaves => "Oak Leaves",
            BlockId::OakPlanks => "Oak Planks",
            BlockId::Brick => "Brick",
            BlockId::Snow => "Snow",
            BlockId::Bedrock => "Bedrock",
            BlockId::CoalOre => "Coal Ore",
            BlockId::IronOre => "Iron Ore",
            BlockId::CraftingTable => "Crafting Table",
            BlockId::Water => "Water",
        }
    }

    /// Seconds of held left-click needed to break this block.
    ///
    /// `None` marks structurally unbreakable blocks (Air has nothing to break,
    /// Bedrock is the world floor). The mining loop treats `None` as "no target".
    pub const fn break_duration_secs(self) -> Option<f32> {
        match self {
            BlockId::Air => None,
            BlockId::Grass => Some(0.5),
            BlockId::Dirt => Some(0.45),
            BlockId::Stone => Some(1.2),
            BlockId::Cobblestone => Some(1.5),
            BlockId::Sand => Some(0.45),
            BlockId::OakLog => Some(0.9),
            BlockId::OakLeaves => Some(0.2),
            BlockId::OakPlanks => Some(0.8),
            BlockId::Brick => Some(1.8),
            BlockId::Snow => Some(0.3),
            BlockId::Bedrock => None,
            BlockId::CoalOre => Some(1.6),
            BlockId::IronOre => Some(2.2),
            BlockId::CraftingTable => Some(0.8),
            // Liquids are not mineable: the mining loop treats `None` as
            // "no target", so a water raycast hit never starts a break.
            BlockId::Water => None,
        }
    }

    /// The block item produced when this block is broken.
    ///
    /// Stone yields Cobblestone so the stone-tier tool recipes (whose head
    /// material is [`BlockId::Cobblestone`]) are reachable through real
    /// gameplay. Every other block drops itself. This is block metadata, not
    /// tool behavior: the mining loop and durability rules are untouched.
    ///
    /// Drops are inventory state only and are never persisted, and the wire
    /// format keeps Cobblestone's id 4 unchanged, so save compatibility is
    /// unaffected.
    pub const fn mined_drop(self) -> BlockId {
        match self {
            BlockId::Stone => BlockId::Cobblestone,
            // Unbreakable ids never reach a drop path; returning the id keeps
            // the mapping total without inventing an item.
            BlockId::Water => BlockId::Water,
            _ => self,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_block_solidity_and_texture_layers() {
        assert!(!BlockId::Air.is_solid());
        assert!(BlockId::Grass.is_solid());
        assert_eq!(BlockId::Grass.face_tex_layer(2), 0);
        assert_eq!(BlockId::Grass.face_tex_layer(3), 2);
        assert_eq!(BlockId::Grass.face_tex_layer(0), 1);
        assert_eq!(BlockId::OakLog.face_tex_layer(2), 6);
        assert_eq!(BlockId::OakLog.face_tex_layer(4), 7);
        assert_eq!(BlockId::Stone.name(), "Stone");
    }

    #[test]
    fn test_block_ids_roundtrip_and_ore_metadata() {
        for id in 0u8..=15 {
            let block = BlockId::from_u8(id).expect("known block id must decode");
            assert_eq!(block as u8, id, "block id {id} must round-trip");
        }
        assert_eq!(BlockId::from_u8(16), None);
        assert_eq!(BlockId::from_u8(99), None);

        assert_eq!(BlockId::Water as u8, 15);
        assert_eq!(BlockId::Water.name(), "Water");

        assert_eq!(BlockId::CoalOre.name(), "Coal Ore");
        assert_eq!(BlockId::IronOre.name(), "Iron Ore");
        assert!(BlockId::CoalOre.is_solid());
        assert!(BlockId::IronOre.is_solid());

        for face_dir in 0u8..6 {
            assert_eq!(BlockId::CoalOre.face_tex_layer(face_dir), 14);
            assert_eq!(BlockId::IronOre.face_tex_layer(face_dir), 15);
        }

        // Crafting table identity is durable block data for the item domain.
        assert_eq!(BlockId::CraftingTable as u8, 14);
        assert_eq!(BlockId::CraftingTable.name(), "Crafting Table");
        assert!(BlockId::CraftingTable.is_solid());
        assert_eq!(BlockId::CraftingTable.break_duration_secs(), Some(0.8));
        for face_dir in 0u8..6 {
            assert_eq!(BlockId::CraftingTable.face_tex_layer(face_dir), 9);
        }
    }

    #[test]
    fn test_only_the_crafting_table_is_table_interactable() {
        for id in 0u8..=15 {
            let block = BlockId::from_u8(id).expect("known block id must decode");
            assert_eq!(
                block.is_table_interactable(),
                block == BlockId::CraftingTable,
                "{block:?} interaction classification drifted"
            );
        }
        assert!(!BlockId::Air.is_table_interactable());
        assert!(!BlockId::Bedrock.is_table_interactable());
        assert!(!BlockId::OakPlanks.is_table_interactable());
        // The classification is additive: table blocks keep their existing
        // solid/breakable behavior.
        assert!(BlockId::CraftingTable.is_solid());
        assert!(BlockId::CraftingTable.break_duration_secs().is_some());
    }

    #[test]
    fn test_break_durations_cover_every_breakable_block() {
        for id in 0u8..=15 {
            let block = BlockId::from_u8(id).expect("known block id must decode");
            match block {
                BlockId::Air | BlockId::Bedrock | BlockId::Water => {
                    assert_eq!(
                        block.break_duration_secs(),
                        None,
                        "{block:?} must be unbreakable"
                    );
                }
                _ => {
                    let duration = block
                        .break_duration_secs()
                        .unwrap_or_else(|| panic!("{block:?} must be breakable"));
                    assert!(duration > 0.0, "{block:?} duration must be positive");
                }
            }
        }
    }

    #[test]
    fn test_mined_drop_is_identity_except_stone_yields_cobblestone() {
        for id in 0u8..=15 {
            let block = BlockId::from_u8(id).expect("known block id must decode");
            let expected = if block == BlockId::Stone {
                BlockId::Cobblestone
            } else {
                block
            };
            assert_eq!(block.mined_drop(), expected, "{block:?} mined drop drifted");
        }
        // Explicit anchors for the two interesting cases.
        assert_eq!(BlockId::Stone.mined_drop(), BlockId::Cobblestone);
        assert_eq!(BlockId::Cobblestone.mined_drop(), BlockId::Cobblestone);
    }

    #[test]
    fn test_solid_and_liquid_matrix_over_every_block_id() {
        // Exactly Air and Water are passable/transparent; Water is the only
        // liquid. Everything else is a solid, non-liquid block.
        for id in 0u8..=15 {
            let block = BlockId::from_u8(id).expect("known block id must decode");
            let expected_solid = !matches!(block, BlockId::Air | BlockId::Water);
            assert_eq!(block.is_solid(), expected_solid, "{block:?} solidity");
            assert_eq!(
                block.is_liquid(),
                block == BlockId::Water,
                "{block:?} liquid"
            );
            if block.is_liquid() {
                assert!(!block.is_solid(), "a liquid cannot also be solid");
            }
        }
        assert!(!BlockId::Air.is_liquid());
        assert!(!BlockId::Bedrock.is_liquid());
        assert!(!BlockId::CraftingTable.is_liquid());
        assert!(BlockId::Water.is_liquid());
        assert!(!BlockId::Water.is_solid());
    }

    #[test]
    fn test_water_metadata_is_worldgen_only() {
        assert_eq!(BlockId::Water as u8, 15);
        assert_eq!(BlockId::Water.name(), "Water");
        assert_eq!(BlockId::Water.break_duration_secs(), None);
        assert_eq!(BlockId::Water.mined_drop(), BlockId::Water);
        for face_dir in 0u8..6 {
            let layer = BlockId::Water.face_tex_layer(face_dir);
            assert!(
                layer <= 15,
                "water layer {layer} must index the 16-layer array"
            );
        }
        assert!(!BlockId::Water.is_table_interactable());
    }

    #[test]
    fn test_break_durations_are_ordered_by_hardness() {
        let leaves = BlockId::OakLeaves.break_duration_secs().unwrap();
        let dirt = BlockId::Dirt.break_duration_secs().unwrap();
        let stone = BlockId::Stone.break_duration_secs().unwrap();
        let coal = BlockId::CoalOre.break_duration_secs().unwrap();
        let iron = BlockId::IronOre.break_duration_secs().unwrap();
        assert!(leaves < dirt, "leaves must be faster than dirt");
        assert!(dirt < stone, "dirt must be faster than stone");
        assert!(stone < coal, "stone must be faster than coal ore");
        assert!(coal < iron, "coal ore must be faster than iron ore");

        let cobblestone = BlockId::Cobblestone.break_duration_secs().unwrap();
        let brick = BlockId::Brick.break_duration_secs().unwrap();
        assert!(brick > cobblestone, "brick must be slower than cobblestone");
    }
}
